svg.script:
//!export-start
let _ps_label = 'Valve';
let _pb_extended = false;
let _pb_retracted = false;
let _pb_extending = false;
let _pb_retracting = false;
let _pb_error = false;
let _pb_isManualMode = false;
//!export-end

const received = {};
const signals = ['_pb_extended', '_pb_retracted', '_pb_extending', '_pb_retracting', '_pb_error', '_pb_isManualMode'];

function render() {
  const label = document.getElementById('valveLabel');
  const body = document.getElementById('valveBody');
  const band = document.getElementById('statusBand');
  const status = document.getElementById('statusText');
  const manualBadge = document.getElementById('manualBadge');
  const manualText = document.getElementById('manualText');
  if (!label || !body || !band || !status || !manualBadge || !manualText) return;

  label.textContent = _ps_label;
  manualBadge.setAttribute('fill', !received._pb_isManualMode ? '#e2e8f0' : (_pb_isManualMode ? '#dbeafe' : '#e2e8f0'));
  manualText.textContent = !received._pb_isManualMode ? 'MODE ?' : (_pb_isManualMode ? 'MANUAL' : 'AUTO');

  let text = 'WAITING FOR DATA';
  let color = '#64748b';
  if (_pb_error) {
    text = 'FAULT';
    color = '#b91c1c';
  } else if ((_pb_extended && _pb_retracted) || (_pb_extending && _pb_retracting)) {
    text = 'CONFLICT';
    color = '#b91c1c';
  } else if (signals.every(signal => received[signal])) {
    if (_pb_extending) {
      text = 'EXTENDING';
      color = '#d97706';
    } else if (_pb_retracting) {
      text = 'RETRACTING';
      color = '#d97706';
    } else if (_pb_extended) {
      text = 'EXTENDED';
      color = '#15803d';
    } else if (_pb_retracted) {
      text = 'RETRACTED';
      color = '#2563eb';
    } else {
      text = 'UNKNOWN';
    }
  }
  status.textContent = text;
  band.setAttribute('fill', color);
  body.setAttribute('fill', color);
}

function putValue(id, value) {
  if (id === '_ps_label') {
    _ps_label = String(value);
  } else if (signals.includes(id)) {
    const normalized = String(value).toLowerCase();
    if (normalized !== 'true' && normalized !== 'false' && normalized !== '1' && normalized !== '0') return;
    const booleanValue = normalized === 'true' || normalized === '1';
    if (id === '_pb_extended') _pb_extended = booleanValue;
    else if (id === '_pb_retracted') _pb_retracted = booleanValue;
    else if (id === '_pb_extending') _pb_extending = booleanValue;
    else if (id === '_pb_retracting') _pb_retracting = booleanValue;
    else if (id === '_pb_error') _pb_error = booleanValue;
    else if (id === '_pb_isManualMode') _pb_isManualMode = booleanValue;
    received[id] = true;
  } else {
    return;
  }
  render();
}

render();
